<script>
document.addEventListener('DOMContentLoaded',function(){
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]})}
  function money(v){return 'KES '+Number(v||0).toLocaleString('en-KE',{maximumFractionDigits:2})}
  function notice(title,html){document.getElementById('notice-title').textContent=title;document.getElementById('notice-body').innerHTML=html;document.getElementById('notice-modal').className='notice-modal open'}
  document.addEventListener('click',function(ev){
    var balance=ev.target.closest('#balance-card,#counter-sales-balance');
    if(balance){
      if(!balance.classList.contains('has-problems')&&!balance.classList.contains('problem'))return;
      var rows=(window.barBalanceRows||[]).filter(function(x){return !x.balanced});
      notice('Sales and items problems','<p>The following sales do not balance:</p><table><thead><tr><th>Sale</th><th>Sale</th><th>Items</th><th>Difference</th></tr></thead><tbody>'+rows.map(function(x){return '<tr><td>#'+x.sale_id+'</td><td>'+money(x.sale_total)+'</td><td>'+money(x.item_total)+'</td><td class="bad">'+money(x.difference)+'</td></tr>'}).join('')+'</tbody></table>');
      return;
    }
    var reqItem=ev.target.closest('.req-day-item');
    if(reqItem){
      if(ev.target.closest('a'))return;
      fetch('api.php?action=requisition_items&req_id='+reqItem.dataset.reqId,{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var a=(r.data||{}).items||[];notice('Requisition #'+reqItem.dataset.reqId,a.length?'<table><thead><tr><th>Item</th><th>Requested</th><th>Issued</th><th>Received</th></tr></thead><tbody>'+a.map(function(x){return '<tr><td>'+esc(x.name)+'</td><td>'+x.requested+'</td><td>'+x.issued+'</td><td>'+x.received+'</td></tr>'}).join('')+'</tbody></table>':'<p>No items found for this requisition.</p>')}).catch(function(){notice('Requisition','<p>Could not load requisition items.</p>')});
      return;
    }
    if(ev.target.closest('#stock-requisitions')){
      fetch('api.php?action=requisitions',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var a=(r.data||{}).requests||[];document.getElementById('stock-request-list').innerHTML=a.length?a.map(function(x){return '<div class="req-day-item" data-req-id="'+x.id+'"><b>#'+x.id+'</b><span><strong>'+esc(x.counter||'This counter')+'</strong><small>'+esc(x.requester)+' · '+x.items+' item(s) · Qty '+x.qty+'</small></span><a href="../rec/rec_pending.php">Receive</a></div>'}).join(''):'<div class="empty">No issued requisitions waiting to be received.</div>'}).catch(function(){});
    }
  });
});
</script>
<script>
/* Visual dashboard bindings layered over the existing API logic. */
(function(){
  function money(v){return 'KES '+Number(v||0).toLocaleString('en-KE',{maximumFractionDigits:0})}
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]})}
  fetch('api.php',{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.json()}).then(function(r){
    var d=(r.data||{}).dashboard||{}, stock=d.stock_summary||{}, balance=d.balance_summary||{};
    var returnAmount=document.getElementById('return-total'), returnCount=document.getElementById('return-count');
    if(returnAmount)returnAmount.textContent=money(d.returns_total||0);
    if(returnCount)returnCount.textContent=(d.returns_count||0)+' returned';
    ['stock-out','stock-out-badge'].forEach(function(id){var n=document.getElementById(id);if(n)n.textContent=stock.out_of_stock||0});
    ['stock-reorder','stock-reorder-badge'].forEach(function(id){var n=document.getElementById(id);if(n)n.textContent=stock.below_reorder||0});
    var totalFlow=document.getElementById('stock-total-flow');if(totalFlow)totalFlow.textContent=stock.total_items||0;
    var button=document.getElementById('counter-sales-balance');
    if(button){button.classList.toggle('problem',balance.balanced===false);button.textContent=balance.balanced===false?'✕ SALES & ITEMS NOT BALANCED':'✓ SALES & ITEMS BALANCED'}
    var total=Number(d.sales_total||0), donutTotal=document.getElementById('donut-total');if(donutTotal)donutTotal.textContent=total>=1000?(total/1000).toFixed(1)+'K':total.toLocaleString('en-KE');
    var rows=(d.counter_sales||[]).slice(0,6), colors=['var(--teal)','var(--blue)','var(--amber)','var(--green)','var(--coral)','var(--navy)'];
    if(rows.length){
      var sum=rows.reduce(function(a,x){return a+Number(x.total||0)},0)||1, acc=0, stops=[];
      rows.forEach(function(x,i){var start=acc;acc+=Number(x.total||0)/sum*100;stops.push(colors[i]+' '+start.toFixed(1)+'% '+acc.toFixed(1)+'%')});
      var donut=document.querySelector('.donut');if(donut)donut.style.background='conic-gradient('+stops.join(',')+')';
      var legend=document.getElementById('sales-legend');if(legend)legend.innerHTML=rows.map(function(x,i){var p=Number(x.total||0)/sum*100;return '<div class="legend-row"><i class="legend-dot" style="background:'+colors[i]+'"></i><span><strong>'+esc(x.label||('Counter '+(i+1)))+'</strong><b>'+money(x.total)+'</b><small>'+p.toFixed(1)+'%</small></span></div>'}).join('');
    }
  }).catch(function(){});
}());
</script>
