:root{--teal:#078b89;--teal-2:#0aa3a0;--blue:#2678c9;--amber:#ffb21a;--green:#08a33b;--navy:#101c38;--soft:#f6f8fa;--line:#e0e6eb;--coral:#ef3340}
html,body{height:auto!important;overflow:auto!important}body{background:#f7f9fb;font-family:Arial,sans-serif;color:var(--navy)}
.main{max-width:none;height:auto!important;display:block!important;padding:16px 20px 28px;overflow:visible!important}.title{min-height:42px;margin:0 0 12px}.title h1{font-size:24px}.title .open{padding:9px 13px;border:1px solid #cde8d5;border-radius:6px;background:#fff}.title-actions a,.title-actions button{height:42px;min-height:42px;padding:0 22px;border-radius:6px;font-size:14px}.title-actions .counter{background:var(--teal)}
.overview{display:grid;grid-template-columns:minmax(480px,1.55fr) minmax(330px,.8fr) minmax(420px,1.05fr);gap:12px;margin-bottom:12px}.hero-sales,.sales-breakdown,.kpi-grid>.metric,.stock-card,.lower>.card{border:1px solid var(--line);border-radius:7px;background:#fff;box-shadow:0 2px 8px rgba(20,40,60,.035)}
.hero-sales{position:relative;min-height:290px;padding:20px 22px 10px;overflow:hidden}.hero-top{display:flex;align-items:flex-start;gap:14px}.hero-icon{display:grid;place-items:center;width:43px;height:43px;border-radius:7px;background:var(--teal);color:#fff;font-size:22px}.hero-copy small{font-size:15px;font-weight:800}.hero-copy strong{display:block;margin-top:4px;color:var(--teal);font-size:38px;line-height:1}.balance-btn{position:absolute;top:36px;right:145px;min-width:220px;height:31px;border:0;border-radius:5px;background:var(--green);color:#fff;font-size:12px;font-weight:900;letter-spacing:.15px}.balance-btn.problem{background:var(--coral)}.change{position:absolute;top:22px;right:22px;text-align:center}.change b{display:block;padding:8px 13px;border:1px solid #cbe8d2;border-radius:6px;color:#07922d;font-size:14px}.change small{display:block;margin-top:7px;color:#536078}.sales-chart{position:absolute;left:22px;right:22px;bottom:14px;height:160px}.sales-chart svg{width:100%;height:100%;overflow:visible}.chart-grid line{stroke:#e4eaee;stroke-width:1}.chart-fill{fill:url(#salesFade)}.chart-line{fill:none;stroke:var(--teal);stroke-width:2.4}.chart-point{fill:var(--teal)}.axis-label{fill:#344361;font-size:10px}
.sales-breakdown{min-height:290px;padding:18px 20px}.sales-breakdown h2{margin:0 0 18px;font-size:16px}.breakdown-body{display:flex;align-items:center;justify-content:center;gap:20px}.donut{position:relative;width:195px;height:195px;flex:0 0 195px;border-radius:50%;background:conic-gradient(var(--teal) 0 32.6%,var(--blue) 32.6% 61.2%,var(--amber) 61.2% 100%)}.donut:after{content:'';position:absolute;inset:41px;border-radius:50%;background:#fff}.donut-center{position:absolute;inset:0;z-index:1;display:grid;place-content:center;text-align:center;font-weight:800}.donut-center b{font-size:24px}.legend{display:grid;gap:14px;min-width:150px}.legend-row{display:grid;grid-template-columns:10px 1fr;gap:8px}.legend-dot{width:10px;height:10px;margin-top:4px;border-radius:50%}.legend-row strong,.legend-row b,.legend-row small{display:block}.legend-row b{margin:3px 0;font-size:15px}.legend-row small{color:#3d5277}
.kpi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0}.kpi-grid>.metric{min-height:290px;border-radius:0;box-shadow:none;padding:20px 12px;justify-content:center;align-items:center}.kpi-grid>.metric:first-child{border-radius:7px 0 0 7px}.kpi-grid>.metric:last-child{border-radius:0 7px 7px 0}.kpi-grid .metric-icon{width:52px;height:52px}.kpi-grid .metric strong{font-size:22px}.kpi-grid .metric span{line-height:1.4}
.stock-card{margin:0 0 12px!important;padding:0}.stock-card .card-head{padding:18px 20px 8px}.stock-card .card-head p,.stock-card .card-head>b{display:none}.stock-flow{display:grid;grid-template-columns:repeat(6,1fr);padding:6px 20px 22px}.flow-item{position:relative;min-height:92px;padding:4px 24px;border-right:1px solid var(--line)}.flow-item:first-child{padding-left:0}.flow-item:last-child{border:0}.flow-icon{display:grid;place-items:center;width:38px;height:38px;margin-bottom:8px;border-radius:8px;background:#e9f6f5;color:var(--teal);font-size:18px}.flow-item strong{display:block;font-size:12px}.flow-item>b{display:block;margin-top:10px;font-size:20px;font-weight:500}.flow-item small{color:#43516b}.alert-badge{display:inline-grid;place-items:center;min-width:28px;height:28px;margin-left:8px;border:1px solid var(--coral);border-radius:50%;background:#fff4f4;color:var(--coral);font-size:14px}.alert-badge.warn{border-color:var(--amber);background:#fff9eb;color:#cc8200}.flow-split{margin-top:10px;font-size:20px}.flow-split small{display:block;margin-top:4px;font-size:11px}
.waiters,#active-sales-card,.metrics{display:none!important}.lower{display:grid!important;grid-template-columns:1.55fr .68fr .88fr!important;gap:12px!important;min-height:340px}.lower>.card{margin:0!important;overflow:hidden}.panel{height:100%;padding:0 20px 14px}.panel-title{padding:17px 0 10px}.panel-title h2{font-size:16px}.panel-title small{font-size:11px}table{font-size:11px;table-layout:auto}th,td{padding:8px 4px}.snap{padding:9px 0;font-size:12px}.snap i{width:27px;height:27px}.performance-row{padding:13px 0}.bar{height:7px}.reprint-cell a{white-space:nowrap}
@media(max-width:1250px){.overview{grid-template-columns:1.4fr .9fr}.kpi-grid{grid-column:1/-1}.kpi-grid>.metric{min-height:110px}.stock-flow{grid-template-columns:repeat(3,1fr);row-gap:20px}.flow-item:nth-child(3){border:0}.lower{grid-template-columns:1fr 1fr!important}.receipts{grid-column:1/-1}.balance-btn{right:130px}}
@media(max-width:700px){.main{padding:10px}.title{flex-wrap:wrap}.title h1{width:100%}.title-actions{width:100%;overflow-x:auto}.overview{display:block}.overview>*{margin-bottom:10px}.hero-sales{min-height:270px}.balance-btn{position:static;display:block;margin:10px 0 0 57px}.change{top:16px}.breakdown-body{flex-wrap:wrap}.kpi-grid>.metric{min-height:95px;padding:10px}.stock-flow{grid-template-columns:repeat(2,1fr);padding:6px 12px 16px}.flow-item:nth-child(2n){border:0}.lower{display:block!important}.lower>.card{margin-bottom:10px!important}.receipts{overflow:auto}.receipts table{min-width:620px}}
</style></head><body>
 
<main class="main"><span hidden id="waiters-count">0</span><span hidden id="open-hours">0</span><div class="title"><h1>Bar Counter Dashboard</h1><span class="open">Counter Open</span><span>|</span><span id="shift">Current Shift</span><span>|</span><span id="date">—</span><div class="title-actions"><a href="../dash/index.php">⌂ &nbsp; Home</a><button onclick="location.reload()">⟳ &nbsp; Refresh</button><a class="counter" href="../counter/open.php">▣ &nbsp; Open Counter</a><a class="logout" href="../log_out.php">⇥ &nbsp; Logout</a></div></div>
<section class="overview">
  <div class="hero-sales">
    <div class="hero-top"><span class="hero-icon">↗</span><div class="hero-copy"><small>Counter Sales — Current Shift</small><strong id="sales">KES 0</strong></div></div>
    <button class="balance-btn" id="counter-sales-balance" type="button">✓ SALES &amp; ITEMS BALANCED</button><span hidden id="sales-balance-percent">100%</span><span hidden id="sales-progress-bar"></span>
    <div class="change"><b>↑ +12.4%</b><small>vs previous shift</small></div>
    <div class="sales-chart"><svg viewBox="0 0 640 150" preserveAspectRatio="none" aria-label="Hourly counter sales chart"><defs><linearGradient id="salesFade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#078b89" stop-opacity=".22"/><stop offset="1" stop-color="#078b89" stop-opacity=".02"/></linearGradient></defs><g class="chart-grid"><line x1="38" y1="18" x2="625" y2="18"/><line x1="38" y1="48" x2="625" y2="48"/><line x1="38" y1="78" x2="625" y2="78"/><line x1="38" y1="108" x2="625" y2="108"/><line x1="38" y1="138" x2="625" y2="138"/></g><path class="chart-fill" d="M42 111 L91 82 L140 61 L189 37 L238 65 L287 87 L336 70 L385 49 L434 27 L483 64 L532 89 L581 112 L620 131 L620 138 L42 138 Z"/><path class="chart-line" d="M42 111 L91 82 L140 61 L189 37 L238 65 L287 87 L336 70 L385 49 L434 27 L483 64 L532 89 L581 112 L620 131"/><g class="chart-point"><circle cx="42" cy="111" r="3.5"/><circle cx="91" cy="82" r="3.5"/><circle cx="140" cy="61" r="3.5"/><circle cx="189" cy="37" r="3.5"/><circle cx="238" cy="65" r="3.5"/><circle cx="287" cy="87" r="3.5"/><circle cx="336" cy="70" r="3.5"/><circle cx="385" cy="49" r="3.5"/><circle cx="434" cy="27" r="3.5"/><circle cx="483" cy="64" r="3.5"/><circle cx="532" cy="89" r="3.5"/><circle cx="581" cy="112" r="3.5"/><circle cx="620" cy="131" r="3.5"/></g><g class="axis-label"><text x="35" y="149">10 AM</text><text x="130" y="149">12 PM</text><text x="228" y="149">2 PM</text><text x="326" y="149">4 PM</text><text x="424" y="149">6 PM</text><text x="522" y="149">8 PM</text><text x="600" y="149">10 PM</text></g></svg></div>
  </div>
  <div class="sales-breakdown"><h2>Sales Breakdown</h2><div class="breakdown-body"><div class="donut"><div class="donut-center"><span>KES</span><b id="donut-total">0</b></div></div><div class="legend" id="sales-legend"><div class="legend-row"><i class="legend-dot" style="background:var(--teal)"></i><span><strong>Counter A</strong><b>KES 21,420</b><small>32.6%</small></span></div><div class="legend-row"><i class="legend-dot" style="background:var(--blue)"></i><span><strong>Counter B</strong><b>KES 18,746</b><small>28.6%</small></span></div><div class="legend-row"><i class="legend-dot" style="background:var(--amber)"></i><span><strong>Main Counter</strong><b>KES 25,450</b><small>38.8%</small></span></div></div></div></div>
  <div class="kpi-grid"><div class="metric"><div class="metric-icon">▤</div><div><small>Total Orders</small><strong id="orders">0</strong><span>Posted this counter</span></div></div><div class="metric"><div class="metric-icon">▱</div><div><small>Active Sales</small><strong id="active-count">0</strong><span>Open in kp_sale_status</span></div></div><div class="metric return"><div class="metric-icon">↻</div><div><small>Returns</small><strong id="return-total">KES 0</strong><span id="return-count">0 returned</span><b hidden id="return-pending"></b><b hidden id="return-approved"></b><b hidden id="return-rejected"></b></div></div></div>
</section>
<section class="stock-card" id="stock-card"><div class="card-head"><div><h2>Counter Stock &amp; Movement</h2><p>Today’s stock activity</p></div><b id="stock-total">0 items</b></div><div class="stock-flow"><div class="flow-item"><i class="flow-icon">◇</i><strong>Stock Items</strong><b id="stock-total-flow">0</b><small>Total items</small></div><div class="flow-item"><i class="flow-icon">!</i><strong>Out of Stock <span class="alert-badge" id="stock-out-badge">0</span></strong><b id="stock-out">0</b><small>Items</small></div><div class="flow-item"><i class="flow-icon">▥</i><strong>Below Reorder <span class="alert-badge warn" id="stock-reorder-badge">0</span></strong><b id="stock-reorder">0</b><small>Items</small></div><div class="flow-item" id="stock-requisitions"><i class="flow-icon">▤</i><strong>Requisitions</strong><div class="flow-split"><b><span id="req-issued">0</span> / <span id="req-received">0</span></b><small>Issued / Received</small></div><b hidden id="req-total"></b><div hidden id="stock-request-list"></div></div><div class="flow-item"><i class="flow-icon">↻</i><strong>Returns</strong><div class="flow-split"><b><span id="return-approved-stock">0</span> / <span id="return-rejected-stock">0</span></b><small>Approved / Rejected</small></div><b hidden id="stock-returns"></b></div><div class="flow-item"><i class="flow-icon">↔</i><strong>Transfers</strong><div class="flow-split"><b><span id="transfer-in">0</span> / <span id="transfer-out">0</span></b><small>In / Out</small></div><b hidden id="stock-transfers"></b><b hidden id="stock-tots"></b><b hidden id="stock-req"></b></div></div></section>
<section class="card waiters"><div class="card-head"><div><h2>Waiters Posted to This Counter</h2><p>Select a waiter to filter receipts and review their totals</p></div><input class="search" id="waiter-search" placeholder="⌕  Search waiter…"></div><div class="waiter-scroll" id="waiter-list"></div><div class="summary" id="summary"></div></section>
<section class="card wide-card" id="active-sales-card"><div class="card-head"><div><h2>Active Sales</h2><p>Open sales currently assigned to this counter</p></div><b id="active-count-label">0</b></div><div class="active-list" id="active-list"><div class="empty">No active sales.</div></div></section>
<div class="lower"><section class="card receipts" id="receipts"><div class="panel"><div class="panel-title"><h2>Last 10 Receipts</h2><small>Most recent receipts posted through this bar counter</small></div><table><thead><tr><th>Receipt</th><th>Waiter</th><th>Time</th><th>Amount</th><th>Status</th></tr></thead><tbody id="receipt-list"></tbody></table></div></section><section class="card"><div class="panel"><div class="panel-title"><h2>Counter Snapshot</h2><small id="opening-info">Opening time: —</small></div><div class="snap"><i>⌁</i><span>Gross Sales</span><b id="gross">KES 0</b></div><div class="snap"><i>▤</i><span>Net Sales</span><b id="net">KES 0</b></div><div class="snap"><i>▣</i><span>Total Orders</span><b id="snap-orders">0</b></div><div class="snap"><i>◇</i><span>Items Sold</span><b id="items">0</b></div><div class="snap"><i>↻</i><span>Returns</span><b id="snap-returns">KES 0</b></div><div class="counter-breakdown"><table><thead><tr><th>Transaction</th><th>Count</th><th>Total</th></tr></thead><tbody id="counter-transactions"></tbody></table></div></div></section><section class="card" id="performance"><div class="panel"><div class="panel-title"><h2>Waiter Performance</h2><small>Current counter · current shift</small></div><div id="performance-list"></div></div></section></div>
</main>
<div class="modal" id="modal"><div class="modal-card"><div class="modal-head"><h2>Select printer</h2><button id="modal-close">×</button></div><div class="printers" id="printers">Loading printers…</div><div class="modal-actions"><button id="modal-cancel">Cancel</button><button class="print" id="modal-print">Print summary</button></div></div></div>
<div class="notice-modal" id="notice-modal"><div class="notice-card"><div class="notice-head"><h2 id="notice-title">Bar notification</h2><button id="notice-close">×</button></div><div class="notice-body" id="notice-body"></div><div class="notice-actions"><button id="notice-ok">OK</button></div></div></div>
<script>
(function(){var S={waiter:0,printer:0,rows:[]};function e(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]})}function m(v){return 'KES '+Number(v||0).toLocaleString('en-KE',{maximumFractionDigits:2})}function ini(n){return String(n||'?').split(/\s+/).slice(0,2).map(function(x){return x[0]}).join('').toUpperCase()}function waiters(rows){S.rows=rows;document.getElementById('waiter-list').innerHTML=rows.length?rows.map(function(w){return '<button class="waiter" data-id="'+w.user_id+'"><span class="initials">'+e(ini(w.name))+'</span><span><strong>'+e(w.name)+'</strong><small>'+w.order_count+' orders <b>'+m(w.sales_total)+'</b></small></span></button>'}).join(''):'<div class="empty">No waiters have posted orders in this shift.</div>'}function performance(rows){var max=Math.max.apply(null,rows.map(function(w){return +w.sales_total}).concat([1]));document.getElementById('performance-list').innerHTML=rows.map(function(w,i){return '<div class="performance-row"><span>'+(i+1)+'</span><span class="initials">'+e(ini(w.name))+'</span><span>'+e(w.name)+'<small> '+w.order_count+' orders</small><div class="bar"><span style="width:'+Math.round(+w.sales_total/max*100)+'%"></span></div></span><b>'+m(w.sales_total)+'</b></div>'}).join('')||'<div class="empty">No performance data.</div>'}function receipts(rows){document.getElementById('receipt-list').innerHTML=rows.length?rows.map(function(r){return '<tr><td><b>#R-'+r.sale_id+'</b></td><td>'+e(r.waiter)+'</td><td>'+e(r.time||'—')+'</td><td>'+m(r.amount)+'</td><td class="status">'+e(r.status)+'</td></tr>'}).join(''):'<tr><td colspan="5" class="empty">No receipts found.</td></tr>'}function summary(id){S.waiter=+id;var box=document.getElementById('summary');box.className='summary open';box.innerHTML='<div class="empty">Loading waiter totals…</div>';fetch('api.php?action=waiter_summary&user_id='+id,{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var d=r.data;var counters=(d.counter_totals||[]).map(function(c){return '<tr><td>'+e(c.counter_name)+'</td><td>'+c.sales_count+'</td><td>'+c.items_count+'</td><td>'+m(c.sales_total)+'</td></tr>'}).join('')||'<tr><td colspan="4" class="empty">No counter breakdown.</td></tr>';box.innerHTML='<div class="summary-head"><h3>'+e(d.waiter.name)+'</h3><small>Position #'+d.position+' · '+e(d.shift||'No shift')+'</small></div><div class="summary-grid"><div class="stat"><small>Sale totals</small><strong>'+m(d.sales_total)+'</strong></div><div class="stat"><small>Sales count</small><strong>'+d.sales_count+'</strong></div><div class="stat"><small>Items sold</small><strong>'+d.items_count+'</strong></div><div class="stat"><small>Returns count</small><strong>'+d.returns_count+'</strong></div><div class="stat"><small>Returns total</small><strong>'+m(d.returns_total)+'</strong></div></div><div class="counter-breakdown"><table><thead><tr><th>Counter</th><th>Sales</th><th>Items sold</th><th>Total</th></tr></thead><tbody>'+counters+'</tbody></table></div><button class="summary-print" id="summary-print">Print summary</button>'})}function close(){document.getElementById('modal').className='modal'}function printers(){S.printer=0;document.getElementById('modal').className='modal open';fetch('api.php?action=print_counters',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var a=r.data.counters||[];document.getElementById('printers').innerHTML=a.map(function(c){return '<button class="printer" data-id="'+c.id+'">'+e(c.name)+'</button>'}).join('')||'<div class="empty">No printers available.</div>'})}document.addEventListener('click',function(x){var w=x.target.closest('.waiter');if(w){summary(w.dataset.id);return}if(x.target.closest('#summary-print')){printers();return}var p=x.target.closest('.printer');if(p){S.printer=+p.dataset.id;document.querySelectorAll('.printer').forEach(function(q){q.classList.toggle('selected',q===p)})}});document.getElementById('modal-close').onclick=close;document.getElementById('modal-cancel').onclick=close;document.getElementById('modal-print').onclick=function(){if(!S.waiter||!S.printer)return;fetch('api.php',{method:'POST',credentials:'same-origin',body:new URLSearchParams({action:'queue_staff_summary',user_id:S.waiter,counter_id:S.printer})}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw Error();close()})};document.getElementById('waiter-search').oninput=function(){var q=this.value.toLowerCase();waiters(S.rows.filter(function(w){return w.name.toLowerCase().indexOf(q)>-1}))};fetch('api.php',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var d=r.data||{},x=d.dashboard||{};document.getElementById('shift').textContent=d.shift||'No Active Shift';document.getElementById('date').textContent=d.shift||'—';document.getElementById('sales').textContent=m(x.sales_total);document.getElementById('orders').textContent=x.orders_total||0;document.getElementById('waiters-count').textContent=x.waiters_total||0;document.getElementById('return-count').textContent=x.returns_count||0;document.getElementById('return-total').textContent=m(x.returns_total)+' returned';document.getElementById('gross').textContent=m(x.sales_total);document.getElementById('net').textContent=m((x.sales_total||0)-(x.returns_total||0));document.getElementById('snap-orders').textContent=x.orders_total||0;document.getElementById('items').textContent=x.items_total||0;document.getElementById('snap-returns').textContent=m(x.returns_total);waiters(d.waiters||[]);receipts(x.recent_receipts||[]);performance(d.waiters||[])})})();
</script></body></html>
<script>
(function(){
  function addReprintActions(){
    var header=document.querySelector('#receipts thead tr');
    if(header && !header.querySelector('.reprint-heading')){var th=document.createElement('th');th.className='reprint-heading';th.textContent='Action';header.appendChild(th)}
    document.querySelectorAll('#receipt-list tr').forEach(function(row){
      if(row.querySelector('.reprint-cell'))return;
      var first=row.querySelector('td');if(!first)return;
      var match=first.textContent.match(/(\d+)/);if(!match)return;
      var td=document.createElement('td');td.className='reprint-cell';td.innerHTML='<a href="../chaba/receipt_counter.php?type=bill&id='+match[1]+'&sale_id='+match[1]+'&return_to=../barp/index.php" style="display:inline-block;padding:6px 10px;border:1px solid #007c7d;border-radius:5px;color:#007c7d;text-decoration:none;font-size:11px;font-weight:800;">⎙ Reprint</a>';row.appendChild(td)
    });
  }
  new MutationObserver(addReprintActions).observe(document.getElementById('receipt-list'),{childList:true});
  addReprintActions();
}());
</script>
<script>
(function(){
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]})}
  function money(v){return 'KES '+Number(v||0).toLocaleString('en-KE',{maximumFractionDigits:2})}
  fetch('api.php',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){
    var d=(r.data||{}).dashboard||{};
    document.getElementById('active-count').textContent=(d.active_sales||[]).length;
    document.getElementById('active-count-label').textContent=(d.active_sales||[]).length;
    document.getElementById('return-pending').textContent=(d.returns_pending||0)+' ('+money(d.returns_pending_total)+')';
    document.getElementById('return-approved').textContent=(d.returns_approved||0)+' ('+money(d.returns_approved_total)+')';
    document.getElementById('return-rejected').textContent=(d.returns_rejected||0)+' ('+money(d.returns_rejected_total)+')';
    document.getElementById('open-hours').textContent=(d.counter_open_hours||0)+'h';
    document.getElementById('opening-info').textContent='Opening time: '+(d.counter_opening||'—')+' · '+(d.counter_open_hours||0)+' hours open';
    document.getElementById('active-list').innerHTML=(d.active_sales||[]).map(function(x){return '<div class="active-item"><b>#'+x.sale_id+'</b><span>'+esc(x.waiter)+'</span><small>'+esc(x.opened_at||'Open')+'</small></div>'}).join('')||'<div class="empty">No active sales.</div>';
    document.getElementById('counter-transactions').innerHTML=(d.counter_transactions||[]).map(function(x){return '<tr><td>'+esc(x.label)+'</td><td>'+x.count+'</td><td>'+money(x.total)+'</td></tr>'}).join('')||'<tr><td colspan="3" class="empty">No transactions.</td></tr>';
    window.barBalanceRows=d.sale_balances||[];
    var problems=window.barBalanceRows.filter(function(x){return !x.balanced}).length;
    var summary=d.balance_summary||{}, salesTotal=+summary.sales_total||0, itemsTotal=+summary.items_total||0;
    var balancePercent=salesTotal>0?Math.min(100,Math.max(0,itemsTotal/salesTotal*100)):100;
    document.getElementById('sales-balance-percent').textContent=Math.round(balancePercent)+'%';
    document.getElementById('sales-progress-bar').style.width=balancePercent+'%';
    document.getElementById('counter-sales-balance').classList.toggle('problem',!summary.balanced);
    var rq=d.requisition_summary||{};
    document.getElementById('req-total').textContent=rq.requests||0;
    document.getElementById('req-issued').textContent=rq.issued||0;
    document.getElementById('req-received').textContent=rq.received||0;
    var stock=d.stock_summary||{};
    document.getElementById('stock-out').textContent=stock.out_of_stock||0;
    document.getElementById('stock-reorder').textContent=stock.below_reorder||0;
    document.getElementById('stock-req').textContent=stock.requisitioned||0;
    document.getElementById('stock-total').textContent=(stock.total_items||0)+' items';
    document.getElementById('stock-returns').textContent=stock.returns||0;
    document.getElementById('return-approved-stock').textContent=stock.returns_approved||0;
    document.getElementById('return-rejected-stock').textContent=stock.returns_rejected||0;
    document.getElementById('stock-tots').textContent=(stock.tots_made||0)+' / '+(stock.tots_qty||0);
    document.getElementById('stock-transfers').textContent=stock.transfers||0;
    document.getElementById('transfer-in').textContent=stock.transfers_in||0;
    document.getElementById('transfer-out').textContent=stock.transfers_out||0;
  });
}());
</script>
<script>
(function(){
  var modal=document.getElementById('notice-modal'), body=document.getElementById('notice-body');
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]})}
  function seen(key,id){var k='barp_notice_'+key+'_'+id; if(sessionStorage.getItem(k))return true; sessionStorage.setItem(k,'1'); return false}
  function show(title,html){document.getElementById('notice-title').textContent=title;body.innerHTML=html;modal.className='notice-modal open'}
  function load(){fetch('api.php?action=notifications',{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.json()}).then(function(r){
    var d=r.data||{}, req=d.requests||[], ret=d.returns||[];
    document.getElementById('stock-request-list').innerHTML=req.length?req.map(function(x){return '<div class="req-day-item" data-req-id="'+x.id+'"><b>#'+x.id+'</b><span><strong>'+esc(x.counter||'This counter')+'</strong><small>'+esc(x.requester)+' · '+x.items+' item(s) · Qty '+x.qty+'</small></span><a href="../rec/rec_pending.php">Receive</a></div>'}).join(''):'<div class="empty">No issued requisitions waiting to be received.</div>';
    if(ret.length && !seen('return',ret[0].id))show('Return waiting for action','<p>A return has been raised for this bar counter.</p><p><b>Receipt #'+ret[0].sale_id+'</b> · '+esc(ret[0].waiter)+' · KES '+Number(ret[0].amount||0).toLocaleString('en-KE')+'</p>');
    else if(req.length && !seen('request',req[0].id))show('Requisition issued','<p>Requisition <b>#'+req[0].id+'</b> has been issued and is waiting for the barman to receive it.</p><p>'+req[0].items+' item(s) · Qty '+req[0].qty+'</p><p><a href="../rec/rec_pending.php">Open receiving screen</a></p>');
  }).catch(function(){});}
  document.getElementById('notice-close').onclick=function(){modal.className='notice-modal'};
  document.getElementById('notice-ok').onclick=function(){modal.className='notice-modal'};
  load();
}());
</script>
<script>
(function(){
  var saleId=0,counterId=0;
  var modal=document.createElement('div');
  modal.id='reprint-modal';
  modal.style='position:fixed;inset:0;z-index:30;display:none;place-items:center;padding:16px;background:#10182b99;';
  modal.innerHTML='<div style="width:min(440px,100%);overflow:hidden;border-radius:10px;background:#fff;"><div style="display:flex;justify-content:space-between;padding:15px;background:#007c7d;color:#fff;"><b>Select counter to reprint</b><button id="reprint-x" style="border:0;background:transparent;color:#fff;font-size:24px;">×</button></div><div id="reprint-counters" style="display:grid;gap:8px;padding:16px;">Loading counters…</div><div style="display:flex;gap:9px;padding:0 16px 16px;"><button id="reprint-cancel" style="flex:1;height:42px;border:0;border-radius:7px;">Cancel</button><button id="reprint-submit" style="flex:1;height:42px;border:0;border-radius:7px;background:#007c7d;color:#fff;font-weight:800;">Reprint</button></div></div>';
  document.body.appendChild(modal);
  function close(){modal.style.display='none'}
  function open(id){saleId=Number(id);counterId=0;modal.style.display='grid';var list=document.getElementById('reprint-counters');list.textContent='Loading counters…';fetch('api.php?action=print_counters',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){var rows=r.data&&r.data.counters||[];list.innerHTML=rows.map(function(c){return '<button class="reprint-counter" data-id="'+c.id+'" style="min-height:45px;border:1px solid #dfe5eb;border-radius:7px;background:#fff;color:#00666c;font-weight:800;">'+String(c.name).replace(/[&<>"']/g,'')+'</button>'}).join('')||'No counters available.'})}
  function mark(){document.querySelectorAll('.reprint-cell a').forEach(function(a){a.classList.add('reprint-link');var x=a.href.match(/[?&](?:sale_id|id)=(\d+)/);if(x)a.dataset.saleId=x[1]})}
  new MutationObserver(mark).observe(document.getElementById('receipt-list'),{childList:true});mark();
  document.addEventListener('click',function(ev){var link=ev.target.closest('.reprint-link');if(link){ev.preventDefault();open(link.dataset.saleId);return}var c=ev.target.closest('.reprint-counter');if(c){counterId=Number(c.dataset.id);document.querySelectorAll('.reprint-counter').forEach(function(x){x.style.background=x===c?'#e0f4f2':'#fff'})}});
  document.getElementById('reprint-x').onclick=close;document.getElementById('reprint-cancel').onclick=close;document.getElementById('reprint-submit').onclick=function(){if(!saleId||!counterId)return;var b=this;b.disabled=true;b.textContent='Queuing…';fetch('api.php',{method:'POST',credentials:'same-origin',body:new URLSearchParams({action:'queue_bill_reprint',sale_id:String(saleId),counter_id:String(counterId)})}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw Error();close();b.disabled=false;b.textContent='Reprint'}).catch(function(){b.disabled=false;b.textContent='Reprint';alert('Could not queue reprint.')})};
}());
</script>
